import{_ as o,l as s,o as e,c as i,v as r,p as l,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"连接顺序搜索空间","description":"","frontmatter":{"title":"连接顺序搜索空间","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/join-order-space.md","filePath":"cs/join-order-space.md","lastUpdated":1789023840000}'),h={name:"cs/join-order-space.md"};function E(u,a,A,_,B,m){const n=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="连接顺序搜索空间" tabindex="-1">连接顺序搜索空间 <a class="header-anchor" href="#连接顺序搜索空间" aria-label="Permalink to &quot;连接顺序搜索空间&quot;">​</a></h1><div class="epigraph"><p>左深树是链，bushy 树允许两侧都是连接结果；再限制「只连接有谓词的分量」，空间从阶乘降到连通子图。</p><footer>—— 据 Vance and Maier；Moerkotte and Neumann, DPCCP；Selinger 左深限制对照</footer></div><p><a href="/cs/selinger-dp">上一课</a>在左深子集 DP 上钉了有趣序。本课不重写支配剪枝。缺口是树形本身：左深、右深、bushy，以及是否允许无连接谓词的笛卡尔积中间结果。空间大小决定 \\(n{=}12\\) 还能不能精确 DP。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>左深：每个连接的一侧是基表。哈希连接时 build 侧若总是「到目前为止的结果」，内存形状固定，流水线友好。bushy：两边都可以是子连接树，有时避免巨大中间结果（两对小连接先做完再连）。右深用于某些并行流水。缺口是<strong>枚举哪些二叉树</strong>，不是再定义 ⋈。</p><p>笛卡尔积：查询图不连通时必须做积。连通查询上，若仍枚举断开子集，会多出极贵的积。DPccp 只枚举连通互补对，空间随查询图稀疏度降。星型查询与链状查询的图完全不同。</p><p><span class="marginnote">Moerkotte and Neumann 的 DPCCP 在连通补对上 DP。Vance and Maier 讨论 bushy 枚举。启发式（GOO、IKKBZ）在 \\(n\\) 太大时替换精确 DP，本课点名不把启发式当最优。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查询图：顶点关系，边是连接谓词。合法连接：两连通分量之间有边（或显式允许积）。左深 DP：状态仍是子集，扩展点必须与 \\(S\\) 有边。bushy DP：状态是子集，转移是拆成两个非空互补连通子集。</p><p>超时与截止：精确搜不完就返回当前最佳（任意时间算法）。这与自适应处理不同：这里还在优化时，尚未执行。</p>',10)),(e(),l(c,null,{default:t(()=>[p(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20QG%5B%22%E6%9F%A5%E8%AF%A2%E5%9B%BE%22%5D%20--%3E%20LD%5B%22%E5%B7%A6%E6%B7%B1%E9%93%BE%22%5D%0A%20%20QG%20--%3E%20BU%5B%22bushy%20%E4%BA%8C%E5%8F%89%E6%A0%91%22%5D%0A%20%20QG%20--%3E%20CC%5B%22%E5%8F%AA%E8%BF%9E%E9%80%9A%E4%BA%92%E8%A1%A5%E5%AF%B9%22%5D%0A%20%20LD%20--%3E%20N1%5B%22n!%20%E9%87%8F%E7%BA%A7%E6%8E%92%E5%88%97%22%5D%0A%20%20BU%20--%3E%20N2%5B%22Catalan%20%C3%97%20%E5%8F%B6%E6%A0%87%22%5D%0A%20%20CC%20--%3E%20N3%5B%22%E9%9A%8F%E7%A8%80%E7%96%8F%E5%BA%A6%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>外连接有顺序限制：不能随便交换左右，bushy 形状更受限。半连接可当缩减器插在真连接前（分布式后课）。代价模型必须给笛卡尔积很高的估计，否则 DP 会「先积再滤」——谓词下推本应先避免积，逻辑改写与物理搜索要配合。</p><p>并行与交换算子后课才加；本课空间仍是逻辑连接树加物理算法标签。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不量化基数误差如何沿 bushy 树爆炸——下一课。也不把遗传算法、模拟退火写进主干必做，只承认 \\(n\\) 很大时近似搜索存在。</p><p>后课默认：谈到连接顺序，先画查询图，再选左深或 bushy、是否强制连通。星型多表不是「随便 nested loop」。</p><p>搜索空间是优化器的复杂度来源；有趣序是每个节点上的标签，不是另一套空间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>左深、bushy、连通限制决定能否精确 DP。</li><li>断开子集等于中间笛卡尔积，通常应禁止。</li><li>基数估计误差传播下一课：空间搜对了，数字错仍选错树。</li><li>出处：Selinger；Vance and Maier；Moerkotte and Neumann。</li></ul>',9))])}const b=o(h,[["render",E]]);export{P as __pageData,b as default};
